import { createHash, randomBytes } from 'node:crypto';

// The Throne game: a sliding puzzle (4x4 = the classic "15 puzzle").
// Every attempt gets its own shuffle, generated by the server from a secret
// seed, so nobody can share a solution. Shuffles are made by random legal
// moves from the solved board (always solvable) and only accepted inside a
// fixed difficulty band, so every player gets a fair, equally hard board.
// The client sends back its list of moves; the server replays them and only
// counts a solve that really ends in the solved position. Time is measured by
// the server (start -> finish), never trusted from the browser.

export const SIZE = 4;
const TILES = SIZE * SIZE; // 15 tiles + the gap (0)
// Difficulty band: sum of Manhattan distances of all tiles from home.
const MIN_DISTANCE = 30;
const MAX_DISTANCE = 36;

// Deterministic PRNG from a seed (sha256 stream), so a board can be rebuilt
// from its seed alone.
function prng(seed) {
  let counter = 0;
  let pool = Buffer.alloc(0);
  return () => {
    if (pool.length < 4) {
      pool = Buffer.concat([pool, createHash('sha256').update(`${seed}:${counter++}`).digest()]);
    }
    const n = pool.readUInt32BE(0);
    pool = pool.subarray(4);
    return n / 0x100000000;
  };
}

const solved = () => [...Array.from({ length: TILES - 1 }, (_, i) => i + 1), 0];

// Positions next to the gap.
function neighbours(gap) {
  const r = Math.floor(gap / SIZE);
  const c = gap % SIZE;
  const out = [];
  if (r > 0) out.push(gap - SIZE);
  if (r < SIZE - 1) out.push(gap + SIZE);
  if (c > 0) out.push(gap - 1);
  if (c < SIZE - 1) out.push(gap + 1);
  return out;
}

export function distance(board) {
  let sum = 0;
  board.forEach((tile, i) => {
    if (!tile) return;
    const home = tile - 1;
    sum += Math.abs(Math.floor(home / SIZE) - Math.floor(i / SIZE)) + Math.abs((home % SIZE) - (i % SIZE));
  });
  return sum;
}

// Builds the board for a seed: random walk from solved until it lands in the
// difficulty band (bounded, deterministic).
export function boardFor(seed) {
  const rand = prng(seed);
  let board = solved();
  let gap = TILES - 1;
  let last = -1;
  for (let step = 0; step < 5000; step++) {
    const options = neighbours(gap).filter((p) => p !== last);
    const pick = options[Math.floor(rand() * options.length)];
    board[gap] = board[pick];
    board[pick] = 0;
    last = gap;
    gap = pick;
    if (step > 60) {
      const d = distance(board);
      if (d >= MIN_DISTANCE && d <= MAX_DISTANCE) return board;
    }
  }
  return board;
}

export const newSeed = () => randomBytes(16).toString('hex');

// Replays a move list. Each move is the index of the tile the player slid
// into the gap (it must be next to the gap). Returns { solved, moves } or
// { error } for an illegal sequence.
export function replay(seed, moves) {
  if (!Array.isArray(moves) || moves.length === 0 || moves.length > 2000) return { error: 'bad-moves' };
  const board = boardFor(seed);
  let gap = board.indexOf(0);
  for (const m of moves) {
    if (!Number.isInteger(m) || m < 0 || m >= TILES || !neighbours(gap).includes(m)) return { error: 'illegal-move' };
    board[gap] = board[m];
    board[m] = 0;
    gap = m;
  }
  const done = board.every((tile, i) => tile === (i === TILES - 1 ? 0 : i + 1));
  return { solved: done, moves: moves.length };
}

// The fastest a human could plausibly make these moves. Anything faster is
// treated as automated and not ranked.
export const minHumanMs = (moves) => Math.max(6000, moves * 140);
